/* ==UserStyle==
@name           Pokemon Charizard
@namespace      userstyles.org
@version        1.0.0
@author         Blugamerplayz
==/UserStyle== */
@-moz-document domain("roblox.com") {
/* Hard override for absolute root backgrounds */
    :root,
    html,
    body,
    #wrap,
    .light-theme,
    .dark-theme, 
    #container-main, 
    .content, 
    .main-layout {
        background-image: url("https://pinimg.com") !important;
        background-color: transparent !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center center !important;
        background-repeat: no-repeat !important;
    }

    /* Target white background layout pieces specifically */
    .rbx-header,
    .left-col-navigation,
    #navigation,
    .content-area,
    .home-header,
    .section,
    .section-content,
    .container-main {
        background: rgba(255, 255, 255, 0.50) !important;
    }
}
